    # str.splitlines would also split on form feeds etc.
    return [l.rstrip("\r") for l in text.split("\n")]


def id_num(s):
    m = re.search(r"\d+", s or "")
    return int(m.group(0)) if m else None


def dec(s):
    return Decimal(str(s).strip())


def to_kg(value, unit):
    return dec(value) * KG[unit.strip().lower()]


def norm_status(s):
    return re.sub(r"[\s\-]+", "_", (s or "").strip().lower())


def utc_date_from_iso(s):
    s = s.strip()
    if "T" not in s and " " not in s:
        return date.fromisoformat(s[:10])
    s = s.replace(" ", "T", 1)
    if s.endswith(("Z", "z")):
        s = s[:-1] + "+00:00"
    dt = datetime.fromisoformat(s)
    if dt.tzinfo is None:
        return dt.date()
    return dt.astimezone(timezone.utc).date()


def rec(num, kind, day, kg, status):
    return {"num": num, "kind": kind, "date": day, "kg": kg, "status": norm_status(status)}


def csv_records(lines):
    """Yield ('comment', text) or ('row', fields-as-list) for delimited text,
    where '#' only starts a comment at the start of a line outside quotes.
    Yields ('raw', line) for rows so the caller picks the delimiter."""
    i = 0
    while i < len(lines):
        line = lines[i]
        i += 1
        if line.startswith("#"):
            yield "comment", line
            continue
        if not line.strip():
            continue
        while line.count('"') % 2 == 1 and i < len(lines):
            line += "\n" + lines[i]
            i += 1
        yield "row", line


def split_row(line, delim):
    return next(csv.reader([line], delimiter=delim))


# ---------- depot parsers: return (seq, [records]) ----------
def parse_central(text):
