    out = []
    for typ, line in csv_records(lines_of(text)):
        if typ == "comment":
            m = re.match(r"#\s*(seq|unit|dates)\s*:\s*(\S+)", line, re.I)
            if m:
                k, v = m.group(1).lower(), m.group(2)
                if k == "seq":
                    seq = int(v)
                elif k == "unit":
                    unit = v.lower()
                else:
                    dfmt = v.upper()
            continue
        f = split_row(line, ",")
        if f and f[0].strip().lower() == "id":
            header = [h.strip().lower() for h in f]
            continue
        if not f or f[0].strip().upper() == "TOTAL" or header is None:
            continue
        r = dict(zip(header, f))
        t = r.get("type", "N").strip().upper()
        kind = {"C": "cor", "V": "void"}.get(t, "new")
        num = id_num(r["id"])
        if kind == "void":
            out.append(rec(num, "void", None, None, ""))
            continue
        s = r["shipped"].strip()
        if dfmt == "DMY":
            d, mo, y = s.split("-")
        else:
            y, mo, d = s.split("-")
        day = date(int(y), int(mo), int(d))
        kg = to_kg(r["gross"].replace(",", ""), unit)
        out.append(rec(num, kind, day, kg, r["status"]))
    return seq, out


def parse_harbor(text):
    seq, header, out = 0, None, []
    for line in lines_of(text):
        if not line.strip():
            continue
        if line.startswith("#"):
            m = re.search(r"seq\s*=\s*(\d+)", line)
            if m:
                seq = int(m.group(1))
            continue
        f = line.split("|")
        if f[0].strip().lower() == "rec":
            header = [h.strip().lower() for h in f]
            continue
        r = dict(zip(header, f))
        t = r["rec"].strip().upper()
        kind = {"COR": "cor", "VOID": "void"}.get(t, "new")
        num = id_num(r["ref"])
        if kind == "void":
            out.append(rec(num, "void", None, None, ""))
            continue
        wv, wu = r["weight"].split()
        st = {"DLV": "delivered", "DLL": "delivered_late", "CAN": "cancelled",
              "RET": "returned", "HLD": "held"}.get(r["state"].strip().upper(), r["state"])
        out.append(rec(num, kind, date.fromisoformat(r["date"].strip()[:10]), to_kg(wv, wu), st))
    return seq, out


def parse_lakeside(text):
    seq, dates, header, out = 0, "iso", None, []
    for typ, line in csv_records(lines_of(text)):
        if typ == "comment":
            m = re.match(r"#\s*(seq|dates)\s*:\s*(\S+)", line, re.I)
            if m:
                if m.group(1).lower() == "seq":
                    seq = int(m.group(2))
                else:
                    dates = m.group(2).lower()
            continue
        f = split_row(line, ",")
        if f and f[0].strip().lower() == "id":
            header = [h.strip().lower() for h in f]
            continue
        r = dict(zip(header, f))
        k = (r.get("kind") or "").strip().lower()
        kind = {"corr": "cor", "void": "void"}.get(k, "new")
        num = id_num(r["id"])
        if kind == "void":
            out.append(rec(num, "void", None, None, ""))
            continue
        s = r["shipped"].strip()
        if dates == "serial":
            day = date(1899, 12, 30) + timedelta(days=int(float(s)))
        else:
            day = date.fromisoformat(s[:10])
        out.append(rec(num, kind, day, to_kg(r["gross_kg"], "kg"), r["status"]))
    return seq, out


def parse_north(text):
    seq, out = 0, []
    for line in lines_of(text):
        line = line.strip()
        if not line:
            continue
        v = json.loads(line)
        items = v if isinstance(v, list) else [v]
        for o in items:
            if not isinstance(o, dict):
                continue
            if "meta" in o:
                seq = int(o["meta"].get("seq", seq))
                continue
            k = (o.get("kind") or "new").lower()
            kind = {"amend": "cor", "void": "void"}.get(k, "new")
            num = id_num(o["id"])
            if kind == "void":
                out.append(rec(num, "void", None, None, ""))
                continue
            wk = next(key for key in o if key.startswith("weight_"))
            kg = to_kg(o[wk], wk.split("_", 1)[1])
            out.append(rec(num, kind, utc_date_from_iso(o["shipped_at"]), kg, o["status"]))
    return seq, out


def parse_river(text):
    seq, fmt, unit, header, out = 0, "MDY", "g", None, []
    for line in lines_of(text):
        if line.startswith("#"):
            m = re.match(r"#\s*seq\s*:\s*(\d+)", line, re.I)
            if m:
                seq = int(m.group(1))
            m = re.match(r"#\s*date format\s*:\s*(\S+)", line, re.I)
            if m:
                fmt = "DMY" if m.group(1).upper().startswith("DD") else "MDY"
            m = re.match(r"#\s*weight unit\s*:\s*(\S+)", line, re.I)
            if m:
                unit = m.group(1).lower()
            continue
        if not line.strip():
            continue
        f = line.split("\t")
        if f[0].strip().lower() == "t" and len(f) > 1 and f[1].strip().lower() == "ref":
            header = [h.strip().lower() for h in f]
            continue
        r = dict(zip(header, f))
        t = (r.get("t") or "").strip().upper()
        kind = {"C": "cor", "V": "void"}.get(t, "new")
        num = id_num(r["ref"])
        if kind == "void":
            out.append(rec(num, "void", None, None, ""))
            continue
        a, b, y = r["shipped"].strip().split("/")
        mo, d = (b, a) if fmt == "DMY" else (a, b)
        out.append(rec(num, kind, date(int(y), int(mo), int(d)),
                       to_kg(r["weight"], unit), r["status"]))
    return seq, out


def parse_west(text):
    seq, unit, header, out = 0, "lb", None, []
    for typ, line in csv_records(lines_of(text)):
        if typ == "comment":
            m = re.match(r"#\s*seq\s*:\s*(\d+)", line, re.I)
            if m:
                seq = int(m.group(1))
            m = re.match(r"#\s*weight unit\s*:\s*([A-Za-z]+)", line, re.I)
            if m:
                unit = m.group(1).lower()
            continue
        f = split_row(line, ";")
        if f and f[0].strip().lower() == "id":
            header = [h.strip().lower() for h in f]
            continue
        r = dict(zip(header, f))
        t = r.get("typ", "N").strip().upper()
        kind = {"C": "cor", "V": "void"}.get(t, "new")
        num = id_num(r["id"])
        if kind == "void":
            out.append(rec(num, "void", None, None, ""))
            continue
        d, mo, y = r["shipped"].strip().split(".")
        w = r["weight"].strip().replace(".", "").replace(",", ".")
        out.append(rec(num, kind, date(int(y), int(mo), int(d)), to_kg(w, unit), r["status"]))
    return seq, out


