    "FW2": dict(type=(1, 1), id=(2, 10), shipped=(11, 18), weight=(19, 26), status=(27, 27),
                date="ymd", wunit=Decimal("0.01")),
    "FW3": dict(id=(1, 9), shipped=(10, 16), type=(17, 17), weight=(18, 24), status=(25, 25),
                date="ydoy", wunit=Decimal("0.045359237")),
}
