    seq, layout, out = 0, None, []
    for line in lines_of(text):
        if "\f" in line or not line.strip():
            continue
        if line.startswith("#"):
            m = re.match(r"#LAYOUT\s+(\S+)", line)
            if m:
                layout = FW[m.group(1)]
            m = re.match(r"#SEQ\s+(\d+)", line)
            if m:
                seq = int(m.group(1))
            continue
        L = layout

        def fld(name):
            a, b = L[name]
            return line[a - 1:b]
        t = fld("type").strip().upper()
        kind = {"C": "cor", "V": "void"}.get(t, "new")
        num = id_num(fld("id"))
        if kind == "void":
            out.append(rec(num, "void", None, None, ""))
            continue
        s = fld("shipped").strip()
        if L["date"] == "ydoy":
            day = date(int(s[:4]), 1, 1) + timedelta(days=int(s[4:]) - 1)
        else:
            day = date(int(s[:4]), int(s[4:6]), int(s[6:8]))
        kg = Decimal(int(fld("weight"))) * L["wunit"]
        out.append(rec(num, kind, day, kg, SOUTH_STATUS.get(fld("status").strip().upper(), "")))
    return seq, out


PARSERS = {"central": parse_central, "east": parse_east, "harbor": parse_harbor,
           "lakeside": parse_lakeside, "north": parse_north, "river": parse_river,
           "south": parse_south, "west": parse_west}


def main(data_dir, out_file):
    exports = {}
    for name in sorted(os.listdir(data_dir)):
        path = os.path.join(data_dir, name)
        if not os.path.isfile(path):
            continue
        depot = name.split("-", 1)[0].lower()
        text = decode(read_bytes(path))
        seq, recs = PARSERS[depot](text)
        exports.setdefault(depot, []).append((seq, name, recs))

    corrections = resends = 0
    current = {}
    for depot, lst in exports.items():
        cur = {}
        for seq, name, recs in sorted(lst, key=lambda x: (x[0], x[1])):
            for r in recs:
                n = r["num"]
                if r["kind"] == "new":
                    if n in cur:
                        resends += 1
                    else:
                        cur[n] = r
                elif r["kind"] == "cor":
                    cur[n] = r
                    corrections += 1
                else:
                    cur.pop(n, None)
                    corrections += 1
        current[depot] = cur

    order = {d: i for i, d in enumerate(PRIORITY)}
    owners = {}
    for depot, cur in current.items():
        for n in cur:
            owners.setdefault(n, []).append(depot)
    handovers = 0
    depots = {d: [0, Decimal(0)] for d in exports}
    months = {}
    for n, ds in owners.items():
        if len(ds) > 1:
            handovers += 1
        d = min(ds, key=lambda x: order.get(x, 99))
        r = current[d][n]
        if r["status"] not in ("delivered", "delivered_late"):
            continue
        depots[d][0] += 1
        depots[d][1] += r["kg"]
        mk = "%04d-%02d" % (r["date"].year, r["date"].month)
        m = months.setdefault(mk, [0, Decimal(0)])
        m[0] += 1
        m[1] += r["kg"]

    def q(x):
        return float(x.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP))
    result = {
        "depots": {d: {"shipments": v[0], "total_kg": q(v[1])} for d, v in sorted(depots.items())},
        "months": {k: {"shipments": v[0], "total_kg": q(v[1])} for k, v in sorted(months.items())},
        "corrections_applied": corrections,
        "resends_dropped": resends,
        "handovers": handovers,
    }
    with open(out_file, "w") as f:
        json.dump(result, f, indent=2)


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
