def parse_lakeside(text):
    seq, dates, header, out = 0, "iso", None, []
    for typ, line in csv_records(lines_of(text)):
        if typ == "comment":
            m = re.match(r"#\s*(seq|dates)\s*:\s*(\S+)", line, re.I)
            if m:
                if m.group(1).lower() == "seq":
                    seq = int(m.group(2))
                else:
                    dates = m.group(2).lower()
            continue
        f = split_row(line, ",")
        if f and f[0].strip().lower() == "id":
            header = [h.strip().lower() for h in f]
            continue
        r = dict(zip(header, f))
        k = (r.get("kind") or "").strip().lower()
        kind = {"corr": "cor", "void": "void"}.get(k, "new")
        num = id_num(r["id"])
        if kind == "void":
            out.append(rec(num, "void", None, None, ""))
            continue
        s = r["shipped"].strip()
        if dates == "serial":
            day = date(1899, 12, 30) + timedelta(days=int(float(s)))
        else:
            day = date.fromisoformat(s[:10])
        out.append(rec(num, kind, day, to_kg(r["gross_kg"], "kg"), r["status"]))
    return seq, out


def parse_north(text):
    seq, out = 0, []
    for line in lines_of(text):
        line = line.strip()
        if not line:
            continue
        v = json.loads(line)
        items = v if isinstance(v, list) else [v]
        for o in items:
            if not isinstance(o, dict):
                continue
            if "meta" in o:
                seq = int(o["meta"].get("seq", seq))
                continue
            k = (o.get("kind") or "new").lower()
            kind = {"amend": "cor", "void": "void"}.get(k, "new")
            num = id_num(o["id"])
            if kind == "void":
                out.append(rec(num, "void", None, None, ""))
                continue
            wk = next(key for key in o if key.startswith("weight_"))
            kg = to_kg(o[wk], wk.split("_", 1)[1])
            out.append(rec(num, kind, utc_date_from_iso(o["shipped_at"]), kg, o["status"]))
    return seq, out


def parse_river(text):
    seq, fmt, unit, header, out = 0, "MDY", "g", None, []
    for line in lines_of(text):
        if line.startswith("#"):
            m = re.match(r"#\s*seq\s*:\s*(\d+)", line, re.I)
            if m:
                seq = int(m.group(1))
            m = re.match(r"#\s*date format\s*:\s*(\S+)", line, re.I)
            if m:
                fmt = "DMY" if m.group(1).upper().startswith("DD") else "MDY"
            m = re.match(r"#\s*weight unit\s*:\s*(\S+)", line, re.I)
            if m:
                unit = m.group(1).lower()
            continue
        if not line.strip():
            continue
        f = line.split("\t")
        if f[0].strip().lower() == "t" and len(f) > 1 and f[1].strip().lower() == "ref":
            header = [h.strip().lower() for h in f]
            continue
        r = dict(zip(header, f))
        t = (r.get("t") or "").strip().upper()
        kind = {"C": "cor", "V": "void"}.get(t, "new")
        num = id_num(r["ref"])
        if kind == "void":
            out.append(rec(num, "void", None, None, ""))
            continue
        a, b, y = r["shipped"].strip().split("/")
        mo, d = (b, a) if fmt == "DMY" else (a, b)
        out.append(rec(num, kind, date(int(y), int(mo), int(d)),
                       to_kg(r["weight"], unit), r["status"]))
    return seq, out


def parse_west(text):
    seq, unit, header, out = 0, "lb", None, []
    for typ, line in csv_records(lines_of(text)):
        if typ == "comment":
            m = re.match(r"#\s*seq\s*:\s*(\d+)", line, re.I)
            if m:
                seq = int(m.group(1))
            m = re.match(r"#\s*weight unit\s*:\s*([A-Za-z]+)", line, re.I)
            if m:
                unit = m.group(1).lower()
            continue
        f = split_row(line, ";")
        if f and f[0].strip().lower() == "id":
            header = [h.strip().lower() for h in f]
            continue
        r = dict(zip(header, f))
        t = r.get("typ", "N").strip().upper()
        kind = {"C": "cor", "V": "void"}.get(t, "new")
        num = id_num(r["id"])
        if kind == "void":
            out.append(rec(num, "void", None, None, ""))
            continue
        d, mo, y = r["shipped"].strip().split(".")
        w = r["weight"].strip().replace(".", "").replace(",", ".")
        out.append(rec(num, kind, date(int(y), int(mo), int(d)), to_kg(w, unit), r["status"]))
    return seq, out


FW = {
    "FW1": dict(id=(1, 9), type=(10, 10), shipped=(11, 17), weight=(18, 25), status=(26, 26),
                date="ydoy", wunit=Decimal("0.001")),
    "FW2": dict(type=(1, 1), id=(2, 10), shipped=(11, 18), weight=(19, 26), status=(27, 27),
                date="ymd", wunit=Decimal("0.01")),
    "FW3": dict(id=(1, 9), shipped=(10, 16), type=(17, 17), weight=(18, 24), status=(25, 25),
                date="ydoy", wunit=Decimal("0.045359237")),
}
SOUTH_STATUS = {"D": "delivered", "L": "delivered_late", "C": "cancelled",
                "R": "returned", "H": "held"}


def parse_south(text):
    seq, layout, out = 0, None, []
    for line in lines_of(text):
        if "\f" in line or not line.strip():
            continue
        if line.startswith("#"):
            m = re.match(r"#LAYOUT\s+(\S+)", line)
            if m:
                layout = FW[m.group(1)]
            m = re.match(r"#SEQ\s+(\d+)", line)
            if m:
                seq = int(m.group(1))
            continue
        L = layout

        def fld(name):
            a, b = L[name]
            return line[a - 1:b]
        t = fld("type").strip().upper()
        kind = {"C": "cor", "V": "void"}.get(t, "new")
        num = id_num(fld("id"))
        if kind == "void":
            out.append(rec(num, "void", None, None, ""))
            continue
        s = fld("shipped").strip()
        if L["date"] == "ydoy":
            day = date(int(s[:4]), 1, 1) + timedelta(days=int(s[4:]) - 1)
        else:
            day = date(int(s[:4]), int(s[4:6]), int(s[6:8]))
        kg = Decimal(int(fld("weight"))) * L["wunit"]
        out.append(rec(num, kind, day, kg, SOUTH_STATUS.get(fld("status").strip().upper(), "")))
    return seq, out


PARSERS = {"central": parse_central, "east": parse_east, "harbor": parse_harbor,
           "lakeside": parse_lakeside, "north": parse_north, "river": parse_river,
           "south": parse_south, "west": parse_west}


def main(data_dir, out_file):
    exports = {}
    for name in sorted(os.listdir(data_dir)):
        path = os.path.join(data_dir, name)
        if not os.path.isfile(path):
            continue
        depot = name.split("-", 1)[0].lower()
        text = decode(read_bytes(path))
        seq, recs = PARSERS[depot](text)
        exports.setdefault(depot, []).append((seq, name, recs))

    corrections = resends = 0
    current = {}
    for depot, lst in exports.items():
        cur = {}
        for seq, name, recs in sorted(lst, key=lambda x: (x[0], x[1])):
            for r in recs:
                n = r["num"]
                if r["kind"] == "new":
                    if n in cur:
                        resends += 1
                    else:
                        cur[n] = r
                elif r["kind"] == "cor":
                    cur[n] = r
                    corrections += 1
                else:
                    cur.pop(n, None)
                    corrections += 1
        current[depot] = cur

    order = {d: i for i, d in enumerate(PRIORITY)}
    owners = {}
    for depot, cur in current.items():
        for n in cur:
            owners.setdefault(n, []).append(depot)
    handovers = 0
    depots = {d: [0, Decimal(0)] for d in exports}
    months = {}
    for n, ds in owners.items():
        if len(ds) > 1:
            handovers += 1
        d = min(ds, key=lambda x: order.get(x, 99))
        r = current[d][n]
        if r["status"] not in ("delivered", "delivered_late"):
            continue
        depots[d][0] += 1
        depots[d][1] += r["kg"]
        mk = "%04d-%02d" % (r["date"].year, r["date"].month)
        m = months.setdefault(mk, [0, Decimal(0)])
        m[0] += 1
        m[1] += r["kg"]

    def q(x):
        return float(x.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP))
    result = {
        "depots": {d: {"shipments": v[0], "total_kg": q(v[1])} for d, v in sorted(depots.items())},
        "months": {k: {"shipments": v[0], "total_kg": q(v[1])} for k, v in sorted(months.items())},
        "corrections_applied": corrections,
        "resends_dropped": resends,
        "handovers": handovers,
    }
    with open(out_file, "w") as f:
        json.dump(result, f, indent=2)


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
